const std = @import("std");
pub const NodeId = packed struct { value: u32, pub fn init(v: u32) NodeId { return .{ .value = v }; } pub fn index(self: NodeId) usize { return self.value; } pub fn raw(self: NodeId) u32 { return self.value; } };
pub const QualName = struct { local: []const u8, ns: []const u8 = "", prefix: ?[]const u8 = null };
pub const Attribute = struct { name: QualName, value: []const u8 };
pub const NodeData = union(enum) { Document, Doctype: struct { name: []const u8, public_id: []const u8, system_id: []const u8 }, Element: struct { name: QualName, attrs: []Attribute, template_contents: ?NodeId = null, mathml_annotation_xml_integration_point: bool = false }, Text: struct { contents: []u8 }, Comment: struct { contents: []const u8 }, ProcessingInstruction: struct { target: []const u8, data: []const u8 } };
pub const Node = struct { data: NodeData, parent: ?NodeId = null, first_child: ?NodeId = null, last_child: ?NodeId = null, prev_sibling: ?NodeId = null, next_sibling: ?NodeId = null };
pub const ChildIterator = struct { tree: *DomTree, next_id: ?NodeId, steps: usize = 0, pub fn next(self: *ChildIterator) ?NodeId { if (self.next_id == null or self.steps >= self.tree.nodes.items.len) return null; const id = self.next_id.?; self.steps += 1; self.next_id = self.tree.nodePtr(id).?.next_sibling; return id; } };
pub const AncestorIterator = struct { tree: *DomTree, next_id: ?NodeId, steps: usize = 0, pub fn next(self: *AncestorIterator) ?NodeId { if (self.next_id == null or self.steps >= self.tree.nodes.items.len) return null; const id = self.next_id.?; self.steps += 1; self.next_id = self.tree.nodePtr(id).?.parent; return id; } };
pub const DescendantIterator = struct { tree: *DomTree, stack: std.ArrayList(NodeId), steps: usize = 0, pub fn deinit(self: *DescendantIterator) void { self.stack.deinit(); } pub fn next(self: *DescendantIterator) ?NodeId { if (self.stack.items.len == 0 or self.steps >= self.tree.nodes.items.len) return null; self.steps += 1; const id = self.stack.pop(); var kids = std.ArrayList(NodeId).init(self.stack.allocator); defer kids.deinit(); var c = self.tree.nodePtr(id).?.first_child; while (c) |x| { kids.append(x) catch break; c = self.tree.nodePtr(x).?.next_sibling; } var i = kids.items.len; while (i > 0) { i -= 1; self.stack.append(kids.items[i]) catch break; } return id; } };
pub const DomTree = struct { allocator: std.mem.Allocator, nodes: std.ArrayList(?Node), free_list: std.ArrayList(u32), document: NodeId, id_index: std.StringHashMap(NodeId), mutex: std.Thread.Mutex = .{},
    pub fn init(a: std.mem.Allocator) !DomTree { var t = DomTree{ .allocator = a, .nodes = std.ArrayList(?Node).init(a), .free_list = std.ArrayList(u32).init(a), .document = NodeId.init(0), .id_index = std.StringHashMap(NodeId).init(a) }; try t.nodes.append(Node{ .data = .Document }); return t; }
    pub fn deinit(self: *DomTree) void { self.nodes.deinit(); self.free_list.deinit(); self.id_index.deinit(); }
    pub fn nodePtr(self: *DomTree, id: NodeId) ?*Node { if (id.index() >= self.nodes.items.len or self.nodes.items[id.index()] == null) return null; return &self.nodes.items[id.index()].?; }
    fn idAttr(n: *Node) ?[]const u8 { if (n.data != .Element) return null; for (n.data.Element.attrs) |a| if (std.ascii.eqlIgnoreCase(a.name.local, "id")) return a.value; return null; }
    pub fn newNode(self: *DomTree, data: NodeData) !NodeId { self.mutex.lock(); defer self.mutex.unlock(); const id = if (self.free_list.items.len > 0) NodeId.init(self.free_list.pop()) else blk: { const v: u32 = @intCast(self.nodes.items.len); try self.nodes.append(null); break :blk NodeId.init(v); }; self.nodes.items[id.index()] = Node{ .data = data }; if (self.nodePtr(id)) |n| if (idAttr(n)) |v| try self.id_index.put(v, id); return id; }
