    fn isAncestor(self: *DomTree, anc: NodeId, id: NodeId) bool { var it = self.ancestors(id); while (it.next()) |x| if (x.raw() == anc.raw()) return true; return false; }
    pub fn appendChild(self: *DomTree, parent: NodeId, child: NodeId) !void { self.mutex.lock(); defer self.mutex.unlock(); if (parent.raw() == child.raw() or self.isAncestor(child, parent)) return error.CycleDetected; self.detachLocked(child); const p = self.nodePtr(parent).?; const c = self.nodePtr(child).?; c.parent = parent; c.prev_sibling = p.last_child; if (p.last_child) |l| self.nodePtr(l).?.next_sibling = child else p.first_child = child; p.last_child = child; }
    pub fn insertBefore(self: *DomTree, parent: NodeId, new_node: NodeId, reference: ?NodeId) !void { if (reference == null) return self.appendChild(parent, new_node); self.mutex.lock(); defer self.mutex.unlock(); if (new_node.raw() == parent.raw() or self.isAncestor(new_node, parent)) return error.CycleDetected; self.detachLocked(new_node); const prev = self.nodePtr(reference.?).?.prev_sibling; const p = self.nodePtr(parent).?; const n = self.nodePtr(new_node).?; n.parent = parent; n.prev_sibling = prev; n.next_sibling = reference; self.nodePtr(reference.?).?.prev_sibling = new_node; if (prev) |x| self.nodePtr(x).?.next_sibling = new_node else p.first_child = new_node; }
    pub fn detach(self: *DomTree, n: NodeId) void { self.mutex.lock(); defer self.mutex.unlock(); self.detachLocked(n); }
    pub fn removeChild(self: *DomTree, parent: NodeId, child: NodeId) void { _ = parent; self.detach(child); }
    pub fn remove(self: *DomTree, n: NodeId) void { self.detach(n); self.nodes.items[n.index()] = null; self.free_list.append(n.raw()) catch {}; }
    pub fn children(self: *DomTree, n: NodeId) ChildIterator { return .{ .tree = self, .next_id = if (self.nodePtr(n)) |x| x.first_child else null }; }
    pub fn ancestors(self: *DomTree, n: NodeId) AncestorIterator { return .{ .tree = self, .next_id = if (self.nodePtr(n)) |x| x.parent else null }; }
    pub fn descendants(self: *DomTree, n: NodeId) DescendantIterator { var s = std.ArrayList(NodeId).init(self.allocator); var c = if (self.nodePtr(n)) |x| x.last_child else null; while (c) |x| { s.append(x) catch break; c = self.nodePtr(x).?.prev_sibling; } return .{ .tree = self, .stack = s }; }
    pub fn getElementById(self: *DomTree, id: []const u8) ?NodeId { return self.id_index.get(id); }
    pub fn textContent(self: *DomTree, n: NodeId) ![]u8 { var out = std.ArrayList(u8).init(self.allocator); if (self.nodePtr(n)) |x| if (x.data == .Text) try out.appendSlice(x.data.Text.contents); var it = self.descendants(n); defer it.deinit(); while (it.next()) |id| if (self.nodePtr(id)) |x| if (x.data == .Text) try out.appendSlice(x.data.Text.contents); return out.toOwnedSlice(); }
    pub fn appendText(self: *DomTree, p: NodeId, text: []const u8) !void { const id = try self.newNode(.{ .Text = .{ .contents = @constCast(text) } }); try self.appendChild(p, id); }
    pub fn findBodyOrRoot(self: *DomTree) NodeId { var it = self.descendants(self.document); defer it.deinit(); while (it.next()) |id| if (self.nodePtr(id)) |n| if (n.data == .Element and std.ascii.eqlIgnoreCase(n.data.Element.name.local, "body")) return id; return self.document; }
    pub fn importChildrenFrom(self: *DomTree, source: *DomTree, source_node: NodeId, dest_parent: NodeId) !void { var it = source.children(source_node); while (it.next()) |id| { const nn = try self.newNode(source.nodePtr(id).?.data); try self.appendChild(dest_parent, nn); try self.importChildrenFrom(source, id, nn); } }
    pub fn updateIdIndex(self: *DomTree, n: NodeId) void { if (self.nodePtr(n)) |x| if (idAttr(x)) |v| self.id_index.put(v, n) catch {}; }
};
test "dom tree" { var t = try DomTree.init(std.testing.allocator); defer t.deinit(); const n = try t.newNode(.{ .Element = .{ .name = .{ .local = "body" }, .attrs = &.{} } }); try t.appendChild(t.document, n); try std.testing.expect(t.findBodyOrRoot().raw() == n.raw()); }

